"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class unnamed_class:
    def __init__(self):
        self.s1 = []
        self.s2 = []

    def enqueue(self, x):
        self.s1.append(x)

    def dequeue(self):
        if (len(self.s2) == 0):
            while (len(self.s1) > 0):
                self.s2.append(self.s1.pop())
        return self.s2.pop()





